async function installationOwner(env){const key=clean(env.ADMIN_KEY);if(!key)throw new ApiError('Set the Worker ADMIN_KEY secret before using /admin.',503,'admin_key_missing');return sha256Hex(`myts-installation:${key}`);}
function bytesToB64(bytes){let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s);}function b64ToBytes(v){const s=atob(v),a=new Uint8Array(s.length);for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return a;}
