async function datasetLinks(request,env){const result=await env.DB.prepare('SELECT dataset_id,family_key,display_name,viewer_token_enc FROM app_datasets ORDER BY display_name').all(),out=[];for(const row of result.results||[])out.push({dataset_id:row.dataset_id,family_key:row.family_key,display_name:row.display_name,viewer_url:await datasetViewerUrl(request,env,row)});return out;}
function requireDatasetFamily(access,publicKey){if(!access?.admin&&clean(access?.family_key)!==clean(publicKey))throw new ApiError('This viewer link does not include that team.',403,'dataset_forbidden');}
