async function tenantStorageKey(owner,publicKey){const familyHash=await sha256Hex(`team-family:${clean(publicKey)}`);return `u:${clean(owner).slice(0,32)}:${familyHash.slice(0,32)}`;}
async function connection(env,key){return env.DB.prepare('SELECT * FROM trace_connections WHERE teamsnap_key=?').bind(key).first();}
async function ownedConnection(env,key,owner){return env.DB.prepare('SELECT * FROM trace_connections WHERE teamsnap_key=? AND owner_hash=?').bind(key,owner).first();}
async function authSession(env,owner){const row=await env.DB.prepare('SELECT * FROM trace_auth_sessions WHERE owner_hash=?').bind(owner).first();if(row?.cookie_header)row.cookie_header=await decryptSecret(env,row.cookie_header);if(row?.token_enc){try{row.trace_token=safeJsonParse(await decryptSecret(env,row.token_enc),null);}catch{row.trace_token=null;}}return row;}
async function pendingAuth(env,owner){const row=await env.DB.prepare('SELECT * FROM trace_auth_pending WHERE owner_hash=?').bind(owner).first();if(row?.guest_cookie)row.guest_cookie=await decryptSecret(env,row.guest_cookie);return row;}
async function tenantKeyFor(env,owner,publicKey){return tenantStorageKey(owner,clean(publicKey));}

