function tsCollectionObjects(payload){return(payload?.collection?.items||[]).map(item=>{const o={};for(const d of item.data||[])if(d?.name)o[d.name]=d.value;for(const l of item.links||[])if(l.rel&&!o[`_link_${l.rel}`])o[`_link_${l.rel}`]=l.href;o._href=item.href||item.links?.find(l=>l.rel==='self')?.href||null;return o;});}
function tsCollectionLink(payload,rel){return payload?.collection?.links?.find(l=>l.rel===rel)?.href||payload?.collection?.items?.flatMap(i=>i.links||[]).find(l=>l.rel===rel)?.href||null;}
async function tsJson(url,token){const res=await fetch(url,{headers:{Authorization:`Bearer ${token}`,Accept:'application/vnd.collection+json, application/json'},cache:'no-store'}),payload=await res.json().catch(()=>({}));if(res.status===401||res.status===403)throw new ApiError('TeamSnap authorization expired. Reconnect TeamSnap from /admin.',401,'teamsnap_auth_expired');if(!res.ok)throw new ApiError(payload?.collection?.error?.message||payload?.error||payload?.message||`TeamSnap request failed (${res.status}).`,502,'teamsnap_request_failed');return payload;}
async function tsFetchCollection(pathOrUrl,params,token){let url=pathOrUrl.startsWith('http')?new URL(pathOrUrl):new URL(`${TEAMSNAP_API}/${pathOrUrl.replace(/^\//,'')}`);for(const[k,v]of Object.entries(params||{}))if(v!==undefined&&v!==null&&v!=='')url.searchParams.set(k,v);if(!url.searchParams.has('page_size'))url.searchParams.set('page_size','100');const out=[],seen=new Set();for(let page=0;url&&page<250;page++){const key=url.toString();if(seen.has(key))break;seen.add(key);const payload=await tsJson(key,token);out.push(...tsCollectionObjects(payload));const next=tsCollectionLink(payload,'next');if(next){url=new URL(next);continue;}const pi=payload?.collection?.page_info;if(pi&&Number(pi.total_items)>out.length&&Number(pi.page_size)>0){url.searchParams.set('page_number',String(Number(pi.page_number??page)+1));continue;}url=null;}return out;}
