function sanitizeTeam(t){return pick(t,['id','name','team_name','label','season_name','season_label','season_title','season','season_start_date','season_end_date','start_date','end_date','starts_at','ends_at','updated_at','modified_at','created_at','created_date','created','is_archived','archived','is_retired','retired','status','location_name','location','city','state','state_code','zip','postal_code']);}
