function discoverTsTeamUrls(payload,me){const urls=new Set(),add=l=>{if(!l?.href)return;const rel=clean(l.rel).toLowerCase();let u;try{u=new URL(l.href);}catch{return;}if(/\/teams(?:\/|$)/i.test(u.pathname)&&['teams','active_teams','archived_teams','past_teams','retired_teams','team_history'].includes(rel))urls.add(u.toString());};for(const l of payload?.collection?.links||[])add(l);for(const item of payload?.collection?.items||[])for(const l of item.links||[])add(l);for(const[k,v]of Object.entries(me||{}))if(k.startsWith('_link_')&&v)add({rel:k.slice(6),href:v});return[...urls];}
async function appConfig(env){return env.DB.prepare('SELECT * FROM app_config WHERE id=?').bind(APP_ID).first();}
async function metaGet(env,key){const r=await env.DB.prepare('SELECT value FROM app_meta WHERE key=?').bind(key).first();return clean(r?.value);}
