const TEAMSYNC_RESOURCES=['events','members','locations','opponents'];
const TEAMSYNC_PAGES_PER_STEP=3;
const RESOURCE_REFRESH_MS={events:null,members:12*60*60*1000,locations:24*60*60*1000,opponents:24*60*60*1000};
const EVENT_WINDOW_REFRESH_MS=30*60*1000;
const EVENT_WINDOW_PAST_MS=21*24*60*60*1000;
const EVENT_WINDOW_FUTURE_MS=180*24*60*60*1000;
function teamSyncPriority(team,resource){const r=Math.max(0,TEAMSYNC_RESOURCES.indexOf(resource)),archived=serverTeamArchived(team)?500:0;return archived+r*20;}
function isoAfter(ms,base=Date.now()){return Number.isFinite(ms)?new Date(base+ms).toISOString():null;}
function resourceNextCheck(team,resource,base=Date.now()){if(serverTeamArchived(team))return null;const ms=RESOURCE_REFRESH_MS[resource];return Number.isFinite(ms)?isoAfter(ms,base):null;}
function teamSnapPageUrl(resource,teamId){const u=new URL(`${TEAMSNAP_API}/${resource}/search`);u.searchParams.set('team_id',String(teamId));if(resource==='events')u.searchParams.set('sort_start_date','asc');u.searchParams.set('page_size','100');return u.toString();}
function nextTeamSnapPageUrl(payload,currentUrl,pageNumber,totalRows){const next=tsCollectionLink(payload,'next');if(next)return next;const pi=payload?.collection?.page_info;if(pi&&Number(pi.total_items)>Number(totalRows||0)&&Number(pi.page_size)>0){const u=new URL(currentUrl);u.searchParams.set('page_number',String(Number(pi.page_number||pageNumber||1)+1));return u.toString();}return'';}
