async function saveTeamCatalogRow(env,team,dataset,stamp){const sanitized=sanitizeTeam(team),text=JSON.stringify(sanitized),hash=await sha256Hex(text),id=String(team.id),old=await env.DB.prepare('SELECT content_hash,data_json FROM app_teams WHERE team_id=?').bind(id).first();if(clean(old?.content_hash)===hash){await env.DB.prepare('UPDATE app_teams SET dataset_id=?,checked_at=? WHERE team_id=?').bind(dataset.dataset_id,stamp,id).run();return false;}await env.DB.prepare(`INSERT INTO app_teams(team_id,dataset_id,data_json,updated_at,content_hash,checked_at) VALUES(?,?,?,?,?,?) ON CONFLICT(team_id) DO UPDATE SET dataset_id=excluded.dataset_id,data_json=excluded.data_json,updated_at=excluded.updated_at,content_hash=excluded.content_hash,checked_at=excluded.checked_at`).bind(id,dataset.dataset_id,text,stamp,hash,stamp).run();return true;}
async function discoverAndSaveTeamSnapTeams(env,token,{mePayload=null,me=null,includeRelated=true}={}){mePayload=mePayload||await tsJson(`${TEAMSNAP_API}/me`,token);me=me||tsCollectionObjects(mePayload)[0]||{};if(me.id==null)throw new ApiError('TeamSnap did not return an account identity.',502,'teamsnap_identity_missing');let searched=[],related=[];try{searched=await tsFetchCollection('teams/search',{user_id:me.id},token);}catch{}if(includeRelated){const urls=discoverTsTeamUrls(mePayload,me);for(const u of urls){try{related.push(...await tsFetchCollection(u,{},token));}catch{}}}const map=new Map();for(const t of [...searched,...related])if(t?.id!=null)map.set(String(t.id),{...(map.get(String(t.id))||{}),...t});const saved=await env.DB.prepare('SELECT data_json FROM app_teams').all();for(const r of saved.results||[]){const t=safeJsonParse(r.data_json,{});if(t?.id!=null&&serverTeamArchived(t)&&!map.has(String(t.id)))map.set(String(t.id),t);}const teams=[...map.values()];if(!teams.length)throw new ApiError('No TeamSnap teams are available for this account.',409,'teamsnap_no_teams');const stamp=now();let changed=0;for(const t of teams){const dataset=await ensureDataset(env,t);if(await saveTeamCatalogRow(env,t,dataset,stamp))changed++;}await metaSet(env,'teamsnap_catalog_checked_at',stamp);return{me,teams,stamp,changed};}
async function queueTeamSnapResource(env,teamId,team,resource,{force=false}={}){const id=String(teamId),job=await env.DB.prepare('SELECT status FROM app_sync_jobs WHERE team_id=? AND resource=?').bind(id,resource).first();if(job&&['pending','syncing'].includes(clean(job.status)))return false;const existing=await env.DB.prepare('SELECT data_json,checked_at,next_check_at FROM app_resources WHERE team_id=? AND resource=?').bind(id,resource).first();if(!force&&existing){const next=clean(existing.next_check_at);if(!next||Date.parse(next)>Date.now())return false;}if(resource==='availabilities'&&existing&&!force)return false;const t=now();await env.DB.prepare('DELETE FROM app_sync_pages WHERE team_id=? AND resource=?').bind(id,resource).run();await env.DB.prepare(`INSERT INTO app_sync_jobs(team_id,resource,next_url,next_page,status,error,priority,started_at,updated_at,completed_at) VALUES(?,?,NULL,1,'pending',NULL,?,NULL,?,NULL) ON CONFLICT(team_id,resource) DO UPDATE SET next_url=NULL,next_page=1,status='pending',error=NULL,priority=excluded.priority,started_at=NULL,updated_at=excluded.updated_at,completed_at=NULL`).bind(id,resource,teamSyncPriority(team,resource),t).run();return true;}
async function queueTeamSnapJobs(env,{full=false,teamId='',force=false,missingOnly=false}={}){const rows=teamId?await env.DB.prepare('SELECT team_id,data_json FROM app_teams WHERE team_id=?').bind(String(teamId)).all():await env.DB.prepare('SELECT team_id,data_json FROM app_teams').all();let queued=0,teams=0;for(const r of rows.results||[]){const team=safeJsonParse(r.data_json,{});if(!full&&serverTeamArchived(team)&&!teamId)continue;teams++;for(const resource of TEAMSYNC_RESOURCES){const existing=await env.DB.prepare('SELECT 1 AS ok FROM app_resources WHERE team_id=? AND resource=?').bind(String(r.team_id),resource).first();if(missingOnly&&existing)continue;const shouldForce=force&&resource!=='events';if(await queueTeamSnapResource(env,r.team_id,team,resource,{force:shouldForce}))queued++;}}if(queued)await env.DB.prepare(`UPDATE app_config SET sync_status='syncing',sync_error=NULL,updated_at=? WHERE id=?`).bind(now(),APP_ID).run();return{queued,teams};}
async function queueDueTeamSnapJobs(env,teamId=''){const rows=teamId?await env.DB.prepare('SELECT team_id,data_json FROM app_teams WHERE team_id=?').bind(String(teamId)).all():await env.DB.prepare('SELECT team_id,data_json FROM app_teams').all();let queued=0;for(const r of rows.results||[]){const team=safeJsonParse(r.data_json,{});if(serverTeamArchived(team))continue;for(const resource of TEAMSYNC_RESOURCES){const rec=await env.DB.prepare('SELECT checked_at,next_check_at FROM app_resources WHERE team_id=? AND resource=?').bind(String(r.team_id),resource).first();if(!rec){if(await queueTeamSnapResource(env,r.team_id,team,resource))queued++;continue;}if(resource==='availabilities')continue;const due=clean(rec.next_check_at);if(due&&Date.parse(due)<=Date.now()&&await queueTeamSnapResource(env,r.team_id,team,resource))queued++;}}return queued;}
async function teamSnapSyncProgress(env){const q=await env.DB.prepare(`SELECT COUNT(*) AS total,SUM(CASE WHEN status='ready' THEN 1 ELSE 0 END) AS ready,SUM(CASE WHEN status='error' THEN 1 ELSE 0 END) AS errors,SUM(CASE WHEN status IN ('pending','syncing') THEN 1 ELSE 0 END) AS pending FROM app_sync_jobs`).first();return{total:Number(q?.total||0),ready:Number(q?.ready||0),errors:Number(q?.errors||0),pending:Number(q?.pending||0)};}
async function pendingForTeam(env,teamId){const r=await env.DB.prepare(`SELECT COUNT(*) AS n FROM app_sync_jobs WHERE team_id=? AND status IN ('pending','syncing')`).bind(String(teamId)).first();return Number(r?.n||0);}
async function updateTeamSnapOverallStatus(env){const p=await teamSnapSyncProgress(env),t=now();let status='ready',error=null;if(p.pending)status='syncing';else if(p.errors){status='partial';error=`${p.errors} TeamSnap resource${p.errors===1?'':'s'} could not refresh.`;}await env.DB.prepare('UPDATE app_config SET sync_status=?,sync_error=?,updated_at=?,last_sync_at=CASE WHEN ?=\'ready\' THEN ? ELSE last_sync_at END WHERE id=?').bind(status,error,t,status,t,APP_ID).run();return{sync_status:status,sync_error:error,progress:p};}
async function publishTeamResource(env,teamId,team,resource,combined){const t=now(),hash=await sha256Hex(combined),rows=(()=>{try{const x=JSON.parse(combined);return Array.isArray(x)?x.length:0;}catch{return 0;}})(),old=await env.DB.prepare('SELECT content_hash,updated_at FROM app_resources WHERE team_id=? AND resource=?').bind(teamId,resource).first(),next=resourceNextCheck(team,resource);if(clean(old?.content_hash)===hash){await env.DB.prepare('UPDATE app_resources SET checked_at=?,next_check_at=?,row_count=? WHERE team_id=? AND resource=?').bind(t,next,rows,teamId,resource).run();return{changed:false,updated_at:old?.updated_at||t,row_count:rows};}await env.DB.prepare(`INSERT INTO app_resources(team_id,resource,data_json,updated_at,content_hash,checked_at,next_check_at,row_count) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(team_id,resource) DO UPDATE SET data_json=excluded.data_json,updated_at=excluded.updated_at,content_hash=excluded.content_hash,checked_at=excluded.checked_at,next_check_at=excluded.next_check_at,row_count=excluded.row_count`).bind(teamId,resource,combined,t,hash,t,next,rows).run();return{changed:true,updated_at:t,row_count:rows};}
function dateOnlyUtc(ms){return new Date(ms).toISOString().slice(0,10);}
