  if(!g)return{ok:true,game:null,status:await statusFor(env,conn,conn.owner_hash)};const raw=await refreshRawSourceIndex(env,conn,key,g.game_id,{});return{ok:true,game:{game_id:String(g.game_id),game_date:g.game_date||null,opponent:g.opponent||'',team_score:g.team_score,opponent_score:g.opponent_score},canonical_players:canonicalPlayersForClaim(conn,g),raw:rawRowSummary(raw),engine_version:RADAR_ENGINE_VERSION,status:await statusFor(env,conn,conn.owner_hash)};
